package com.example.fdbatch;
import com.example.fdsecurity.JwtBeans;import com.example.fdsecurity.ResourceServerSupport;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.security.oauth2.jwt.JwtDecoder;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.core.userdetails.User;import org.springframework.security.provisioning.InMemoryUserDetailsManager;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity @Import(JwtBeans.class) public class SecurityConfig {
 @Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();}
 @Bean InMemoryUserDetailsManager users(PasswordEncoder e){return new InMemoryUserDetailsManager(User.withUsername("admin1").password(e.encode("admin123")).roles("ADMIN").build(),User.withUsername("officer1").password(e.encode("officer123")).roles("BANK_OFFICER").build());}
 @Bean SecurityFilterChain chain(HttpSecurity h,ObjectProvider<JwtDecoder> jwt,JwtAuthenticationConverter conv,@Value("${app.security.basic.enabled:true}") boolean basic)throws Exception{h.csrf(c->c.disable()).authorizeHttpRequests(a->a.anyRequest().authenticated());ResourceServerSupport.apply(h,jwt,conv,basic);return h.build();}
}
